import{_ as s,l as r,o as e,c as l,v as t,p as d,x as i,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"访问者与遍","description":"","frontmatter":{"title":"访问者与遍","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ast-visitor.md","filePath":"cs/ast-visitor.md","lastUpdated":1789023840000}'),h={name:"cs/ast-visitor.md"};function m(_,a,A,E,f,u){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="访问者与遍" tabindex="-1">访问者与遍 <a class="header-anchor" href="#访问者与遍" aria-label="Permalink to &quot;访问者与遍&quot;">​</a></h1><div class="epigraph"><p>树的形状固定，操作随遍增加：把遍历做成访问者，类型检查、解释、IR 生成各写一组 visit，而不改节点类。</p><footer>—— 据 Gamma et al., Design Patterns, 1994；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/ast">抽象语法树</a>交出压缩后的有序树，并声明后课要遍历。本课不重定义 BinOp。缺口是<strong>遍</strong>（pass）怎么挂在树上：递归函数按节点种类分支，或访问者把「对每种节点做什么」从树节点里拆出去。<a href="/cs/compiler-passes">编译器通行证</a>已有管道；本课把管道的前端段落实为 AST 上的多次行走。符号表还没有，visit 遇到 <code>id</code> 仍只看见字符串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每个新分析都改节点类加方法，节点会膨胀成上帝对象。访问者：<code>visit(BinOp)</code>、<code>visit(If)</code>…，双分派或手工 <code>switch</code> 种类。一遍可以综合属性（自底向上求值），一遍可以继承属性（自顶向下传作用域）。语法制导定义里的综合/继承与此对应，本课用遍历实现，不把属性文法公理写完。</p><p>遍的次序：先解析绑定，再类型，再 IR。错序会在未绑定的名字上查类型。本课只钉「多遍、每遍一种职责」，查找规则下一课。</p><h3 id="访问者不是图算法-dfs-的别名" tabindex="-1">访问者不是图算法 DFS 的别名 <a class="header-anchor" href="#访问者不是图算法-dfs-的别名" aria-label="Permalink to &quot;访问者不是图算法 DFS 的别名&quot;">​</a></h3><p>AST 是树，一般无共享（公共子表达式前）。遍历是树递归，不是 CFG 上的数据流。不要把后课活跃变量的迭代当成 visit 一遍就结束。</p><p><span class="marginnote">GoF Visitor。Appel 的每章一棵树加一组 visit。龙书用语法制导，动作写在产生式上，与归约时构造 AST 是同一遍历的不同时机。本课允许分析期再走树，不必全在归约瞬间做完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义节点代数数据类型。写 <code>Visitor</code>：默认递归孩子，再覆盖要做事的种类。遍与遍之间可把结果写回节点字段（类型、绑定指针）或另建并行结构。错误继续遍历以便多报。</p>',11)),(e(),d(c,null,{default:i(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AST%5B%22AST%22%5D%20--%3E%20V1%5B%22%E9%81%8D%EF%BC%9A%E7%BB%93%E6%9E%84%E6%A3%80%E6%9F%A5%22%5D%0A%20%20V1%20--%3E%20V2%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%91%E5%AE%9A%22%5D%0A%20%20V2%20--%3E%20V3%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%B1%BB%E5%9E%8B%20%2F%20IR%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/tree-as-acyclic">树</a> 的无环保证递归终止。若语言允许图（已有命名类型的环），visit 要备「正在走」标记，那是类型课的名义类型，本课点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前端管道 = 词法、语法、若干 AST 遍。中端换成 CFG 就不再用本课的树访问者，而用块上的迭代。本课不开始填符号表，但 visit 进入 <code>Block</code> 时将是 push 作用域的位置——下一课接。</p><p>不要为了访问者模式把简单编译器写成框架地狱；函数式语言里一组函数定义即访问者。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解析名字、不检查类型、不生成三地址。不把解释器当必选遍。后课默认：会对 AST 走遍。作用域与符号表层叠是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遍 = 对 AST 的一次职责单一的遍历；访问者把操作从节点拆出。</li><li>综合自底向上，继承自顶向下。</li><li>绑定尚未发生；下一课符号表。</li><li>出处：Gamma et al., 1994；Appel, <em>Modern Compiler Implementation</em>。</li></ul>',8))])}const S=s(h,[["render",m]]);export{T as __pageData,S as default};
